loadTasks() {
  const now = getNow()

  // 获取历史待办 ID 集合
  const historyIds = getHistoryTasks(now, getTaskHistoryDays()).map(t => t.id)

  // 已逾期待办（排除已归入历史的）
  this.overdueTasks = getOverdueTasks(now).filter(t => !historyIds.includes(t.id)).map(t => ({
    ...t,
    deadlineText: this.formatDeadline(t.deadline),
    countdown: getTaskCountdown(t, now),
    countdownText: formatTaskCountdown(t, now)
  }))

  // 今日待办（排除已归入历史的）
  this.todayTasks = getTodayTasks(now).filter(t => !historyIds.includes(t.id)).map(t => ({
    ...t,
    deadlineText: this.formatDeadline(t.deadline),
    countdown: getTaskCountdown(t, now),
    countdownText: formatTaskCountdown(t, now)
  }))

  // 本周待办（排除已归入历史的）
  this.weekTasks = getWeekTasks(now).filter(t => !historyIds.includes(t.id)).map(t => ({
    ...t,
    deadlineText: this.formatDeadline(t.deadline),
    countdown: getTaskCountdown(t, now),
    countdownText: formatTaskCountdown(t, now)
  }))

  // 未来待办（排除已归入历史的）
  this.futureTasks = getFutureTasks(now).filter(t => !historyIds.includes(t.id)).map(t => ({
    ...t,
    deadlineText: this.formatDeadline(t.deadline),
    countdown: getTaskCountdown(t, now),
    countdownText: formatTaskCountdown(t, now)
  }))

  // 已完成（排除已归入历史的）
  this.finishedTasks = getFinishedTasks().filter(t => !historyIds.includes(t.id)).map(t => ({
    ...t,
    deadlineText: this.formatDeadline(t.deadline)
  }))

  // 计算待处理总数
  this.pendingCount = this.overdueTasks.length + this.todayTasks.length + this.weekTasks.length + this.futureTasks.length
},

